mapper.select:
select f.id, f.flow_no, f.account_id, f.customer_id, c.name as customer_name,
       f.biz_type, f.biz_id, f.biz_no, f.direction, f.amount,
       f.balance_before, f.balance_after,
       f.bill_id, f.bill_no, f.contract_id,
       f.operator, u.user_name as operator_name,
       f.create_time as flow_time, f.remark
from crm_customer_account_flow f
left join crm_customer c on f.customer_id = c.id
left join sys_user u on f.operator = u.user_id

     and f.customer_id = #{customerId}
     and f.biz_type = #{bizType}
     and f.direction = #{direction}
     and f.bill_no like concat('%', #{billNo}, '%')
     and f.flow_no like concat('%', #{flowNo}, '%')

        and c.owner_user = #{params.ownerUser}


        and f.create_time >= #{params.beginTime}


        and f.create_time <= #{params.endTime}


order by f.id desc

select ifnull(sum(case when direction = 1 then amount else -amount end), 0)
from crm_customer_account_flow
where account_id = #{accountId}
